## What problem(s) does this PR solve?

- Effectively closes https://github.com/godotengine/godot-proposals/issues/15255
	Since a plugin can now be used for it.
- Alternative to https://github.com/godotengine/godot/pull/123592

Exposes `Window::_window_input` as `handle_input`.

## Additional information

`DisplayServer.window_set_input_event_callback` was exposed which allows users to override the input that a window gets entirely. But it was not possible to only intercept the event and continue with regular input handling, because the default implementation is not exposed. Also if a user wants to stop overriding the input and go back to the default handler, they have to use a workaround like sending a mouse enter notification.
This is especially important for popups and other Window child classes that use `Window::_input_from_window`, which is not exposed.

<details><summary>Touch Input Emulator plugin</summary>

```gdscript
@tool
extends EditorPlugin

var stolen_windows := []

func _enter_tree() -> void:
	var root := get_tree().root
	_take_window_input(root)
	if not root.gui_embed_subwindows:
		root.mouse_exited.connect(_connect_to_window)
		root.focus_exited.connect(_connect_to_window)

func _exit_tree() -> void:
	_return_all_window_input()

func _connect_to_window() -> void:
	var window_id := DisplayServer.window_get_active_popup()
	if window_id == DisplayServer.INVALID_WINDOW_ID:
		window_id = DisplayServer.get_window_at_screen_position(DisplayServer.mouse_get_position())
	if window_id == DisplayServer.INVALID_WINDOW_ID or window_id == DisplayServer.MAIN_WINDOW_ID:
		return

	var win_obj_id := DisplayServer.window_get_attached_instance_id(window_id)
	var window := instance_from_id(win_obj_id) as Window
	if window == null:
		printerr("Failed to connect to window ", window_id)
		return

	if not window.mouse_exited.is_connected(_connect_to_window):
		# Window focus exited isn't emitted for popups so also connect to mouse exit.
		window.mouse_exited.connect(_connect_to_window)
		window.focus_exited.connect(_connect_to_window)
	_take_window_input(window)

func _take_window_input(window: Window)-> void:
	var win_obj_id := window.get_instance_id()
	if stolen_windows.has(win_obj_id):
		return
	var window_id := window.get_window_id()
	if window_id == DisplayServer.INVALID_WINDOW_ID:
		printerr("Window `%s` is invalid" % window.name)
		return

	#print("Taking window input for window `%s`" % window.name)
	stolen_windows.push_back(win_obj_id)
	DisplayServer.window_set_input_event_callback(_window_input.bind(window_id), window_id)
	window.tree_exited.connect(_window_exited.bind(window))
	window.visibility_changed.connect(_window_exited.bind(window))

func _window_exited(window: Window) -> void:
	if window.visible and window.is_inside_tree():
		return
	#print("Window `%s` exited" % [window.name])
	_return_window_input(window)

func _return_window_input(window: Window)-> void:
	window.tree_exited.disconnect(_window_exited)
	window.visibility_changed.disconnect(_window_exited)
	
	var win_obj_id := window.get_instance_id()
	stolen_windows.erase(win_obj_id)

	var window_id := window.get_window_id()
	#print("Returning input to window %s `%s`" %[window_id, window.name])
	if window_id == DisplayServer.INVALID_WINDOW_ID:
		#printerr("Window `%s` is invalid" % window.name)
		return
	DisplayServer.window_set_input_event_callback(window.handle_input, window_id)

func _return_all_window_input() -> void:
	#print("Returning window input")
	var all_stolen := stolen_windows.duplicate()
	for win_obj_id in all_stolen:
		var window := instance_from_id(win_obj_id) as Window
		if window == null:
			printerr("Failed to get to window ", win_obj_id)
			continue
		_return_window_input(window)
	
	stolen_windows.clear()

func _window_input(event: InputEvent, window_id: int) -> void:
	if not DisplayServer.get_window_list().has(window_id):
		printerr("_window_input Nonexistent window %s" % window_id)
		return
	var win_obj_id := DisplayServer.window_get_attached_instance_id(window_id)
	var window := instance_from_id(win_obj_id) as Window
	if window == null:
		printerr("_window_input Failed to get to window ", window_id)
		return
	
	#print("stole input from window %s : %s" % [window_id, event])
	
	if event.device == InputEvent.DEVICE_ID_EMULATION:
		return

	var pan_multiplier := 15
	var mb := event as InputEventMouseButton
	if mb:
		var vertical_wheel = mb.button_index == MOUSE_BUTTON_WHEEL_UP or mb.button_index == MOUSE_BUTTON_WHEEL_DOWN
		var horizontal_wheel = mb.button_index == MOUSE_BUTTON_WHEEL_LEFT or mb.button_index == MOUSE_BUTTON_WHEEL_RIGHT
		if vertical_wheel or horizontal_wheel:
			var pan_event := InputEventPanGesture.new()
			pan_event.position = mb.position
			if vertical_wheel:
				var flip := -1 if mb.button_index == MOUSE_BUTTON_WHEEL_UP else 1
				pan_event.delta = Vector2(0, mb.factor * flip) * pan_multiplier
			else:
				var flip := -1 if mb.button_index == MOUSE_BUTTON_WHEEL_LEFT else 1
				pan_event.delta = Vector2(mb.factor * flip, 0) * pan_multiplier
			pan_event.window_id = mb.window_id
			_send_input_to_window(pan_event, window)
			return

		# emulate mouse from touch
		# the setting won't work as we already missed where it applies in Input, so do it manually
		var emulated_event := event.duplicate()
		emulated_event.device = InputEvent.DEVICE_ID_EMULATION
		_send_input_to_window(emulated_event, window)

		if mb.button_index == MOUSE_BUTTON_LEFT or mb.button_index == MOUSE_BUTTON_RIGHT:
			var touch_event := InputEventScreenTouch.new()
			touch_event.pressed = mb.pressed
			touch_event.canceled = mb.canceled
			touch_event.position = mb.position
			touch_event.double_tap = mb.double_click
			touch_event.long_press = mb.button_index == MOUSE_BUTTON_RIGHT
			touch_event.window_id = mb.window_id
			_send_input_to_window(touch_event, window)
		return
	
	var mm := event as InputEventMouseMotion
	if mm:
		if mm.button_mask & MOUSE_BUTTON_MASK_MIDDLE:
			var pan_event := InputEventPanGesture.new()
			pan_event.position = mm.position
			pan_event.delta = -mm.relative
			pan_event.window_id = mm.window_id
			_send_input_to_window(pan_event, window)
			return
		

		if mm.button_mask & MOUSE_BUTTON_MASK_LEFT or mm.button_mask & MOUSE_BUTTON_MASK_RIGHT:
			# emulate mouse from touch
			var emulated_event := event.duplicate()
			emulated_event.device = InputEvent.DEVICE_ID_EMULATION
			_send_input_to_window(emulated_event, window)
		
			var drag_event := InputEventScreenDrag.new()
			drag_event.position = mm.global_position
			drag_event.relative = mm.relative
			drag_event.screen_relative = mm.screen_relative
			drag_event.tilt = mm.tilt
			drag_event.pen_inverted = mm.pen_inverted
			drag_event.pressure = mm.pressure
			drag_event.velocity = mm.velocity
			drag_event.screen_velocity = mm.screen_velocity
			drag_event.window_id = mm.window_id
			_send_input_to_window(drag_event, window)
		return
	
	_send_input_to_window(event, window)

func _send_input_to_window(event: InputEvent, window: Window) -> void:
	#print("Sending to `%s` %s" % [window.name, event])
	window.handle_input(event)

```

